"""Derive SkyyRebirth/build_skyyrebirth_0.3.4.py from SkyyRebirth/build_skyyrebirth_0.3.3.py (= the tools/deploy_set.py SET pin, GENERATED by
tools/rebirth_0_3_3_patch.py). rep(old, new) with asserted anchors; 0.3.3 stays untouched; its line endings are kept; every change is checked
at the end to prove nothing else changed.
Run:  python tools/rebirth_0_3_4_patch.py   then   python SkyyRebirth/build_skyyrebirth_0.3.4.py   (NO --deploy: coordinated deploy)
Test: python SkyyRebirth/test_skyyrebirth_0.3.4.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all)

0.3.4 (2026-10-16) = REBIRTH ON BY DEFAULT (Skyy 2026-10-16, popup "REBIRTH: keep it switched OFF for real players until you've tested
it?" -> "turn it on. me and my friends are the only real players. and we are all here to test it. SO dont gate anything for 'Other
players' we will decide what to lock when the time comes for release."; docs/answered/economy.md 2026-10-16 REBIRTH ON + NO GATES).
  - rebirth.on defaults to TRUE: the Server Setup row default, a fresh config.properties (rebirth.on=true + the run-once marker line), a
    file with no rebirth.on line and an unreadable file (RbCfg.loadCfg's fallback) all read ON. Switching it OFF in Server Setup still
    works (the row keeps confirm=on for switching it ON).
  - ONE-TIME MIGRATION RbCfg.migOn (PROJECT-RULES section 4; SkyyWardrobe 0.2.2 WdCfg.migFree's reviewed machinery = SkyySkills 0.4.38
    RbCoinMig's) in setup() BEFORE RbCfg.loadCfg and CfgPub.start, ONCE on an EXISTING config.properties: rebirth.on whose LAST entry is a
    one-line entry holding exactly "false" (the old untouched default) -> every such one-line entry "true" (value text only; key,
    separator, CR kept); NO rebirth.on entry (it read the old code default false) -> rebirth.on=true appended; any other value (true, a
    continued value, "FALSE", "no", ...) is an admin's choice: KEPT (an INFO line). A change = one config-changes.log line rebirth.on
    false -> true (Server Setup -> Changes -> Undo = false). The run-once marker comment goes right under the last (or the appended)
    entry, in the file's own line ending (a fresh 0.3.4 file already carries it, so migOn never touches it). Properties check (only
    rebirth.on differs / is added), config-history copy FIRST (verified: it holds exactly the old bytes), the kit's atomicWrite. A
    failure = WARN, the file untouched (rebirth stays as the file says), the next start tries again.
  No saved-data, bridge, command or page change. ROLLBACK to 0.3.3: safe - 0.3.3 reads rebirth.on=true as an admin's value (rebirth stays
  ON; switch it off in Server Setup first if that is wanted); the marker is a comment.
"""
import difflib
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.3.py")
dst = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.4.py")
raw = open(src, "rb").read()
NL = "\r\n" if b"\r\n" in raw else "\n"
assert NL == "\n" or raw.count(b"\r\n") == raw.count(b"\n"), "mixed line endings in 0.3.3"
s = raw.decode("utf8").replace("\r\n", "\n")
LF = "\n"
S0 = s
assert 'VERSION = "0.3.3"' in s and "GENERATED by tools/rebirth_0_3_3_patch.py" in s, "not the generated 0.3.3"
OLDS = []


def rep(old, new, count=1):
    global s
    n = s.count(old)
    assert n == count, "anchor count %d (want %d): %s" % (n, count, old[:160])
    s = s.replace(old, new)
    OLDS.append(old)


HEAD = open(__file__, encoding="utf8").read().split('"""')[1]
NOTE = HEAD[HEAD.index("0.3.4 (2026-10-16)"):].rstrip() + "\n"

# ---------------------------------------------------------------- docstring + version
rep('''"""SkyyRebirth 0.3.3 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_3_patch.py from build_skyyrebirth_0.3.2.py (itself
generated by tools/rebirth_0_3_2_patch.py from 0.3.1, generated by tools/rebirth_0_3_1_patch.py from 0.3, generated by tools/rebirth_0_3_patch.py
''',
    '''"""SkyyRebirth 0.3.4 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_4_patch.py from build_skyyrebirth_0.3.3.py (itself
generated by tools/rebirth_0_3_3_patch.py from 0.3.2, generated by tools/rebirth_0_3_2_patch.py from 0.3.1, generated by tools/rebirth_0_3_1_patch.py
from 0.3, generated by tools/rebirth_0_3_patch.py
''')
rep('''Run:   python SkyyRebirth/build_skyyrebirth_0.3.3.py   -> SkyyRebirth/SkyyRebirth-0.3.3.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.3.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)

''', '''Run:   python SkyyRebirth/build_skyyrebirth_0.3.4.py   -> SkyyRebirth/SkyyRebirth-0.3.4.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.4.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)

''' + NOTE + '''  CHECKED: SkyyRebirth/test_skyyrebirth_0.3.4.py.

''')
rep('VERSION = "0.3.3"\n', 'VERSION = "0.3.4"\n')

# ---------------------------------------------------------------- the default file: rebirth.on=true + the run-once marker
rep('''# ================= config text (the kit's DEFAULTS and the mod's own first-run file are the same text) =================
CONFIG_TEXT = "\\n".join([''', '''# ================= config text (the kit's DEFAULTS and the mod's own first-run file are the same text) =================
# 0.3.4: the run-once marker of the rebirth.on false -> true update (a fresh 0.3.4 file carries it, so RbCfg.migOn never touches it)
ON_MIG_ID = "skyyrebirth-0.3.4-on"
ON_MARK = "# %s: Rebirth (whole feature) false -> true checked once (SkyyRebirth 0.3.4) - keep this line" % ON_MIG_ID
CONFIG_TEXT = "\\n".join([''')
rep('''    "# rebirth.on = the whole rebirth feature. false (default): players cannot open /rebirth; admins (skyyrebirth.admin) can view it",
    "# and test it with /rebirthadmin + the tree. true: every player at max class level can rebirth from /rebirth (resets their skills, purse",
    "# and bank) and every player can spend rebirth points in the tree.",
    "rebirth.on=false",''',
    '''    "# rebirth.on = the whole rebirth feature. true (default since 0.3.4): every player at max class level can rebirth from /rebirth",
    "# (resets their skills, purse and bank) and every player can spend rebirth points in the tree. false: players cannot open /rebirth;",
    "# admins (skyyrebirth.admin) can view it and test it with /rebirthadmin + the tree.",
    "rebirth.on=true",
    ON_MARK,''')
rep('''for f in ("public static volatile boolean ON = false;",''', '''for f in ("public static volatile boolean ON = true;",''')
rep('''    ("rebirth.on", "Rebirth (whole feature)", "rebirth", "bool", "false", "", "", "", "", "live,danger",''',
    '''    ("rebirth.on", "Rebirth (whole feature)", "rebirth", "bool", "true", "", "", "", "", "live,danger",''')
rep('''NOTE="Off by default. Admins test it with /rebirthadmin (dryrun, crashtest, points, refund).",''',
    '''NOTE="On by default (0.3.4). Admins test it with /rebirthadmin (dryrun, crashtest, points, refund).",''')
rep('''  ON = bool(p.getProperty("rebirth.on"), false);''', '''  ON = bool(p.getProperty("rebirth.on"), true);   // 0.3.4: ON by default''')

# ---------------------------------------------------------------- RbCfg.migOn (after RbCfg.info / warn / loadCfg; the kit is emitted before)
ON_MIG = r'''
assert CONFIG_TEXT.count("\nrebirth.on=true\n" + ON_MARK + "\n") == 1
# 0.3.4 RbCfg.migOn (PROJECT-RULES section 4 one-time setting migration; SkyyWardrobe 0.2.2 WdCfg.migFree's reviewed machinery): ONCE on an
# EXISTING config.properties, in setup() BEFORE RbCfg.loadCfg and CfgPub.start (Skyy 2026-10-16: "turn it on."). Nothing to do = no file
# (loadCfg writes the 0.3.4 default, marker included) or a comment line holding ON_MIG_ID (done before). Else, per logical line (the kit's own
# parser): rebirth.on whose LAST entry is a one-line entry holding exactly false (the old default) -> every such one-line entry true (value
# text only; key, separator, CR kept); NO rebirth.on entry (it read the code default false) -> rebirth.on=true appended; any other value is
# an admin's choice: KEPT (an INFO line). A change = one config-changes.log line rebirth.on false -> true (Server Setup -> Changes -> Undo =
# false). The marker goes right under the last (or the appended) entry, in the file's own line ending. Properties check (only rebirth.on
# differs / is added), config-history copy FIRST (verified: it holds exactly the old bytes), the kit's atomicWrite. A failure = WARN, the
# file untouched, the next start tries again.
F(cfg, "public static final String MIG_ID = %s;" % jlit(ON_MIG_ID))
F(cfg, "public static final String MIG_MARK = %s;" % jlit(ON_MARK))
F(cfg, 'public static final String MIG_KEY = "rebirth.on";')
F(cfg, 'public static final String MIG_OLD = "false";')
F(cfg, 'public static final String MIG_NEW = "true";')
F(cfg, 'public static final String MIG_WHO = "SkyyRebirth 0.3.4";')
F(cfg, "public static volatile String MIG_LAST = null;")   # what the last migOn did (harness / log)
M(cfg, r"""
public static Object[] migPlan(String text) {
  if (text == null) return null;
  java.util.Properties p = new java.util.Properties();
  try { p.load(new java.io.StringReader(text)); } catch (Throwable t) { return null; }
  String[] raw = text.split("\n", -1);
  java.util.ArrayList l = new java.util.ArrayList();
  for (int i = 0; i < raw.length; i++) {
    String s0 = raw[i];
    if (s0.endsWith("\r")) s0 = s0.substring(0, s0.length() - 1);
    l.add(s0);
  }
  String eff = null;
  boolean multi = false;
  int lastEnd = -1;
  int k = 0;
  while (k < l.size()) {
    String s = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s)) {
      if (s.indexOf(MIG_ID) >= 0) return null;
      k++;
      continue;
    }
    int e = @PKG@.CfgFile.end(l, k);
    if (MIG_KEY.equals(@PKG@.CfgFile.key(s))) { eff = @PKG@.CfgFile.value(l, k).trim(); multi = e > k; lastEnd = e; }
    k = e + 1;
  }
  boolean add = eff == null;
  boolean mig = add || (!multi && eff.equals(MIG_OLD));
  String kept = !mig ? MIG_KEY + "=" + @PKG@.CfgRows.oneLine(p.getProperty(MIG_KEY)) + " kept (an admin's value) - the 0.3.4 default is true (rebirth on)" : "";
  String cr = text.indexOf("\r\n") >= 0 ? "\r" : "";
  java.util.ArrayList out = new java.util.ArrayList();
  boolean placed = false;
  k = 0;
  while (k < l.size()) {
    String s2 = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s2)) { out.add(raw[k]); k++; continue; }
    int e2 = @PKG@.CfgFile.end(l, k);
    if (mig && !add && MIG_KEY.equals(@PKG@.CfgFile.key(s2)) && e2 == k && @PKG@.CfgFile.value(l, k).trim().equals(MIG_OLD)) {
      out.add(s2.substring(0, @PKG@.CfgFile.valStart(s2)) + MIG_NEW + (raw[k].endsWith("\r") ? "\r" : ""));
    } else {
      for (int q = k; q <= e2; q++) out.add(raw[q]);
    }
    if (e2 == lastEnd && e2 + 1 < raw.length) {
      out.add(MIG_MARK + (raw[e2].endsWith("\r") ? "\r" : cr));
      placed = true;
    }
    k = e2 + 1;
  }
  StringBuilder sb = new StringBuilder(text.length() + 256);
  for (int i = 0; i < out.size(); i++) {
    if (i > 0) sb.append('\n');
    sb.append((String) out.get(i));
  }
  String body = sb.toString();
  if (!placed) {
    String nl = cr + "\n";
    String pre = (body.length() == 0 || body.endsWith("\n")) ? "" : nl;
    String last = body.endsWith("\n") ? body.substring(0, body.length() - 1) : body;
    if (last.endsWith("\r")) last = last.substring(0, last.length() - 1);
    int bs = 0;
    for (int i = last.length() - 1; i >= 0 && last.charAt(i) == '\\'; i--) bs++;
    if (bs % 2 == 1) pre = pre + nl;
    body = body + pre + (add ? MIG_KEY + "=" + MIG_NEW + nl : "") + MIG_MARK + nl;
  }
  String[] rows = mig ? new String[] { MIG_KEY, MIG_OLD, MIG_NEW } : new String[0];
  return new Object[] { body, rows, Boolean.valueOf(mig), kept, Boolean.valueOf(add) };
}""")
M(cfg, r"""
public static boolean migSame(byte[] old, byte[] nb, boolean mig, boolean add) {
  try {
    java.util.Properties a = new java.util.Properties();
    java.util.Properties n = new java.util.Properties();
    a.load(new java.io.ByteArrayInputStream(old));
    n.load(new java.io.ByteArrayInputStream(nb));
    if (n.size() != a.size() + (add ? 1 : 0)) return false;
    if (add && (a.getProperty(MIG_KEY) != null || !MIG_NEW.equals(n.getProperty(MIG_KEY)))) return false;
    java.util.Iterator it = a.stringPropertyNames().iterator();
    while (it.hasNext()) {
      String k = (String) it.next();
      String want = a.getProperty(k);
      if (mig && MIG_KEY.equals(k)) want = MIG_NEW;
      String got = n.getProperty(k);
      if (got == null || !got.equals(want)) return false;
    }
    return true;
  } catch (Throwable t) { return false; }
}""")
M(cfg, r"""
public static int migFileIdx() {
  for (int k = 0; k < @PKG@.CfgRows.FILES.length; k++) if (@PKG@.CfgRows.FILES[k].endsWith("/config.properties")) return k;
  return -1;
}""")
M(cfg, r"""
public static boolean migSaved(int f, byte[] old) {
  String[] have = @PKG@.CfgHist.list(f);
  for (int i = have.length - 1; i >= 0; i--) {
    try { if (java.util.Arrays.equals(java.nio.file.Files.readAllBytes(@PKG@.CfgHist.bak(f, have[i])), old)) return true; } catch (Throwable x) { }
  }
  return false;
}""")
M(cfg, r"""
public static String migLine(String k, String o, String n) {
  return @PKG@.CfgLog.now() + "\t" + MIG_WHO + "\t-\tupdate\t" + @PKG@.CfgRows.oneLine(k) + "\t" + o + "\t" + n + "\tok";
}""")
# f = mods/Skyy_SkyyRebirth/config.properties; the kit's HOME / LOG are set by setup() first (CfgPub.start sets the same later)
M(cfg, r"""
public static synchronized String migOn(java.nio.file.Path f) {
  MIG_LAST = "";
  if (f == null) return "";
  try {
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return "";
    byte[] old = java.nio.file.Files.readAllBytes(f);
    Object[] r = migPlan(new String(old, "ISO-8859-1"));
    if (r == null) return "";
    byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
    boolean mig = ((Boolean) r[2]).booleanValue();
    boolean add = ((Boolean) r[4]).booleanValue();
    if (!migSame(old, data, mig, add)) {
      warn("config.properties NOT updated for 0.3.4 (rebirth on): the update would change another setting (the file is used as it is; the next start tries again)");
      return "";
    }
    int fi = migFileIdx();
    if (fi < 0) return "";
    @PKG@.CfgHist.snapshot(fi, old, @PKG@.CfgHist.stamp(), MIG_WHO, "before the 0.3.4 rebirth on update (false -> true)");
    if (!migSaved(fi, old)) {
      warn("config.properties NOT updated for 0.3.4 (rebirth on): the old file could not be kept in config-history (the next start tries again)");
      return "";
    }
    @PKG@.CfgRows.atomicWrite(f, data);
    String[] rows = (String[]) r[1];
    for (int i = 0; i + 2 < rows.length; i += 3) @PKG@.CfgLog.enqueue(migLine(rows[i], rows[i + 1], rows[i + 2]));
    if (rows.length > 0) @PKG@.CfgLog.flush();
    String msg = "config.properties updated for 0.3.4: " + (mig ? MIG_KEY + " false -> true" + (add ? " (line added - the file had none and read false)" : "") + " (rebirth is ON for every player, Skyy 2026-10-16; Server Setup -> Changes -> Undo = false)" : "no setting changed - 0.3.4 marker added") + " - the old file is in config-history";
    info(msg);
    String kept = (String) r[3];
    if (kept.length() > 0) { info(kept); msg = msg + "\n" + kept; }
    MIG_LAST = msg;
    return msg;
  } catch (Throwable t) {
    warn("could not update config.properties for 0.3.4 (rebirth on; the file is used as it is): " + t);
    return "";
  }
}""")
'''
rep('''# ================= RbStore: Skyy_SkyyRebirth/players/''', ON_MIG.lstrip(LF) + '''# ================= RbStore: Skyy_SkyyRebirth/players/''')

# ---------------------------------------------------------------- setup(): migOn before loadCfg / CfgPub.start
rep('''  @PKG@.RbCfg.FILE = dir.resolve("config.properties");
  String c = @PKG@.RbCfg.loadCfg(true);''', '''  @PKG@.RbCfg.FILE = dir.resolve("config.properties");
  // 0.3.4: the one-time rebirth.on false -> true update of an existing config.properties, BEFORE loadCfg / CfgPub.start (the kit's history +
  // change log folder and logger first; CfgPub.start sets the same again)
  try {
    @PKG@.CfgRows.LOG = getLogger();
    @PKG@.CfgRows.HOME = dir;
    @PKG@.CfgHist.init();
    @PKG@.CfgLog.init();
    @PKG@.RbCfg.migOn(@PKG@.RbCfg.FILE);
  } catch (Throwable t) { @PKG@.RbCfg.warn("the 0.3.4 rebirth on update was skipped: " + t); }
  String c = @PKG@.RbCfg.loadCfg(true);''')

# ---------------------------------------------------------------- manifest
rep('''man = B.manifest("SkyyRebirth", VERSION, "SkyWynn Rebirth (New Game+), first part - OFF by default.''',
    '''man = B.manifest("SkyyRebirth", VERSION, "SkyWynn Rebirth (New Game+) - ON by default since 0.3.4 (an untouched old rebirth.on=false is switched on once).''')

# ---------------------------------------------------------------- checks
assert s.count('"rebirth.on=false"') == 0 and s.count('"rebirth.on=true"') == 1 and s.count('"bool", "false"') == 0, "the default file / row say true"
_a, _b = S0.split(LF), s.split(LF)
_hunks = [op for op in difflib.SequenceMatcher(None, _a, _b, autojunk=False).get_opcodes() if op[0] != "equal"]
_gone = [(i, _a[i]) for op in _hunks for i in range(op[1], op[2])]
_allowed = set()
for _o in OLDS:
    _allowed.update(_o.split(LF))
_bad = [(i, ln) for i, ln in _gone if ln not in _allowed and not any(_o in ln for _o in OLDS if LF not in _o)]
assert not _bad, "0.3.3 lines changed outside the planned places: %r" % _bad[:5]
if os.path.exists(dst):
    os.remove(dst)
compile(s, dst, "exec")
open(dst, "wb").write(s.replace(LF, NL).encode("utf8"))
print("wrote", dst, len(s), "chars;", len(_hunks), "diff hunks vs 0.3.3,", len(_gone), "0.3.3 lines replaced;", len(OLDS), "anchors")
